insert into e30_guide_snapshots (revision, content) values
  ('53f48962aec9e91fa4d67936', '{"slug":"e30-wheel-removal","title":"Remove or install a wheel","system":"suspension","engines":["M20"],"level":"Beginner","kind":"replacement","duration":"15–25 min","durationBasis":"Planning estimate for stock hardware in serviceable condition.","summary":"U.S. E30 325i / 325is, stock wheel and bolts described in the owner’s handbook.","reviewStatus":"draft","sourceChecked":true,"applicability":"U.S. E30 325i / 325is, stock wheel and bolts described in the owner’s handbook.","source":{"id":"e30-factory-repair-upload","title":"BMW E30 Repair Manual","section":"36-6 · 36 10 300","pdfPages":[724]},"evidence":[{"label":"BMW · 36-6, wheel removal and installation","href":"/manual/36?pdf=724"},{"label":"BMW E30 torque manual · 36-1 · PDF 144","href":"https://www.allcarmanuals.com/factory-service-manual-343-BMW-3-Series-E30.html"},{"label":"1991 325i coupe · cross-spoke wheel diagram","href":"https://www.bmwpartsdeal.com/parts-list/1991-bmw-325i-coupe_e30/wheels/cross_spoke_styling.html"}],"tools":["Wheel bolt wrench or matching socket, chock and calibrated torque wrench. Use the wheel-lock key if fitted."],"cautions":["Chock the wheels and support the car on rated stands or a lift before removing a wheel. A jack alone is insufficient.","Use 110 Nm for the stock wheel and bolts covered by the U.S. handbook. Check the wheel maker’s spec for aftermarket hardware."],"jobSupport":{"reviewedOn":"2026-11-16","sourceSha256":"fa72b3321315a2f2a0f4df6d6879eae4ec7c639f8b0f6f41fd154adcb0a4f095","requiredParts":[],"conditionalParts":[],"stopConditions":[],"steps":[{"number":1,"tools":[],"source":{"printed":"36-6 · 36 10 300","pdf":724,"href":"/manual/36?pdf=724"}},{"number":2,"tools":[],"source":{"printed":"36-6 · 36 10 300","pdf":724,"href":"/manual/36?pdf=724"}},{"number":3,"tools":[],"source":{"printed":"36-6 · 36 10 300","pdf":724,"href":"/manual/36?pdf=724"}}]},"steps":[{"title":"Chock the car and loosen the bolts","body":"Park on level ground. Loosen each bolt slightly with the wheel on the ground. Raise and support the car at the specified points.","check":"The wheel is off the ground and the car is stable."},{"title":"Inspect the seats and mating faces","body":"Support the wheel while removing the bolts. Clean the flat hub and wheel mating faces. Check that the replacement bolt seat and length match the wheel.","check":"The wheel sits flat against the hub and all bolts start by hand."},{"title":"Tighten in a cross pattern","body":"Snug the bolts evenly in a cross pattern, then use the specified torque with the wheel held against turning.","check":"Every bolt reached the applicable torque."}]}'::jsonb),
  ('7f8fb2a97c180172d92e4250', '{"slug":"e30-front-brake-pads-discs","title":"Front brake pads and discs","system":"brakes","engines":["M20"],"level":"Intermediate","kind":"replacement","duration":"1–2 hr per axle","durationBasis":"Planning estimate for stock hardware in serviceable condition.","summary":"1991 U.S. 325i coupe, M20, rear-wheel drive. Factory ventilated front discs and matching sliding calipers; iX hardware differs.","reviewStatus":"draft","sourceChecked":true,"applicability":"1991 U.S. 325i coupe, M20, rear-wheel drive. Factory ventilated front discs and matching sliding calipers; iX hardware differs.","source":{"id":"e30-factory-repair-upload","title":"BMW E30 Repair Manual","section":"34-4 to 34-5 · front pads and discs","pdfPages":[643,644]},"evidence":[{"label":"BMW · 34-4, front brake pads and caliper","href":"/manual/34?pdf=643"},{"label":"BMW · 34-5, front disc removal","href":"/manual/34?pdf=644"},{"label":"1991 325i coupe · front caliper and pads diagram","href":"https://www.bmwpartsdeal.com/parts-list/1991-bmw-325i-coupe_e30/brakes_pedals/front_wheel_brake_brake_pad_sensor.html"},{"label":"1991 325i coupe · front disc diagram","href":"https://www.bmwpartsdeal.com/parts-list/1991-bmw-325i-coupe_e30/brakes_pedals/front_brake_brake_disc.html"}],"tools":["Counterhold wrench on the guide pin. Check the hex on the fitted caliper.","Disc micrometer, caliper hanger, rated stands and torque wrench."],"cautions":["Chock the wheels and support the car on rated stands or a lift before removing a wheel. A jack alone is insufficient.","Keep grease off the disc and lining. Support the caliper independently of its hose.","Pump the pedal until firm before moving the car. Stop if the pedal sinks, a leak appears or the brakes drag.","Check the caliper design first. This sequence covers the bolt-to-guide-pin design with the 35 Nm fastener."],"jobSupport":{"reviewedOn":"2026-11-16","sourceSha256":"fa72b3321315a2f2a0f4df6d6879eae4ec7c639f8b0f6f41fd154adcb0a4f095","requiredParts":["Matched front pad set and new guide-pin bolts.","Two matching discs if the discs are being replaced."],"conditionalParts":[],"stopConditions":[],"steps":[{"number":1,"tools":[],"source":{"printed":"34-4 to 34-5 · front pads and discs","pdf":643,"href":"/manual/34?pdf=643"}},{"number":2,"tools":[],"source":{"printed":"34-4 to 34-5 · front pads and discs","pdf":643,"href":"/manual/34?pdf=643"}},{"number":3,"tools":[],"source":{"printed":"34-4 to 34-5 · front pads and discs","pdf":644,"href":"/manual/34?pdf=644"}},{"number":4,"tools":[],"source":{"printed":"34-4 to 34-5 · front pads and discs","pdf":643,"href":"/manual/34?pdf=643"}}]},"steps":[{"title":"Check the caliper and disc","body":"Remove the front wheels. Compare the caliper and guide fasteners to BMW’s illustration. Check the disc with a micrometer and confirm the minimum thickness for that disc.","check":"The guide-pin bolt design, pad set and disc match the installed hardware."},{"title":"Remove the pads","body":"Disconnect the wear sensor if fitted. Counterhold the guide pin while removing the retaining bolt. Hang the caliper and remove the pads.","check":"No tension or twist is on the hose."},{"title":"Remove or check the disc","body":"For replacement, remove the carrier and disc screw. Clean the hub mating face and check that the new disc sits flat. Tighten the retaining screw to 16 Nm and the carrier bolts to 123 Nm on this RWD application with the factory thread preparation.","check":"The disc sits flat and turns without interference."},{"title":"Install pads and check pedal","body":"Press the piston back with a spreader while watching reservoir level. Fit the pads and sensor, renew the illustrated guide-pin bolts and tighten them to 35 Nm. Refit the wheels, pump the pedal and check braking at low speed.","check":"The pedal is firm and both front brakes operate normally."}]}'::jsonb),
  ('b4646474531c6feb73dbcf35', '{"slug":"e30-rear-brake-pads-discs","title":"Rear brake pads and discs","system":"brakes","engines":["M20"],"level":"Intermediate","kind":"replacement","duration":"1–2 hr per axle","durationBasis":"Planning estimate for stock hardware in serviceable condition.","summary":"1991 U.S. 325i coupe, M20, rear-wheel drive. Factory rear discs and the capped guide bolts in BMW’s illustration.","reviewStatus":"draft","sourceChecked":true,"applicability":"1991 U.S. 325i coupe, M20, rear-wheel drive. Factory rear discs and the capped guide bolts in BMW’s illustration.","source":{"id":"e30-factory-repair-upload","title":"BMW E30 Repair Manual","section":"34-8 to 34-9 · rear pads and discs","pdfPages":[647,649]},"evidence":[{"label":"BMW · 34-8, rear brake pads and caliper","href":"/manual/34?pdf=647"},{"label":"BMW · 34-9, rear disc removal","href":"/manual/34?pdf=649"},{"label":"1991 325i coupe · rear brake diagram","href":"https://www.bmwpartsdeal.com/parts-list/1991-bmw-325i-coupe_e30/brakes_pedals/rear_wheel_brake_brake_pad_sensor.html"}],"tools":["7 mm hex bit for the factory rear guide bolts.","Disc micrometer, caliper hanger, rated stands and torque wrench."],"cautions":["Chock the wheels and support the car on rated stands or a lift before removing a wheel. A jack alone is insufficient.","Keep grease off the disc and lining. Support the caliper independently of its hose.","Pump the pedal until firm before moving the car. Stop if the pedal sinks, a leak appears or the brakes drag.","Chock the car independently of the parking brake. Release that brake before removing the rear discs."],"jobSupport":{"reviewedOn":"2026-11-16","sourceSha256":"fa72b3321315a2f2a0f4df6d6879eae4ec7c639f8b0f6f41fd154adcb0a4f095","requiredParts":["Matched rear pad set.","Two matching discs if the discs are being replaced."],"conditionalParts":[],"stopConditions":[],"steps":[{"number":1,"tools":[],"source":{"printed":"34-8 to 34-9 · rear pads and discs","pdf":647,"href":"/manual/34?pdf=647"}},{"number":2,"tools":[],"source":{"printed":"34-8 to 34-9 · rear pads and discs","pdf":649,"href":"/manual/34?pdf=649"}},{"number":3,"tools":[],"source":{"printed":"34-8 to 34-9 · rear pads and discs","pdf":649,"href":"/manual/34?pdf=649"}}]},"steps":[{"title":"Remove the pads","body":"Remove the caps and use a 7 mm hex bit on the original guide bolts. Hang the caliper. Note the positions of the pads and retaining spring.","check":"The rear caliper is supported and the pads match the replacements."},{"title":"Fit the rear discs","body":"Remove the carrier and retaining screw. Back off the parking brake shoe adjuster if the disc will not release. Clean the hub face and inspect the shoe linings before seating the new disc.","check":"The disc seats flat and the parking brake shoes stay in place."},{"title":"Refit and check","body":"Tighten the disc screw to 16 Nm, the carrier to 67 Nm and the original 7 mm guide bolts to 30 Nm with −5 Nm tolerance. Restore the parking brake adjustment and pump the service pedal before driving.","check":"Both discs turn freely with the brake released and hold when applied."}]}'::jsonb),
  ('65304222a2c127857bf8e39b', '{"slug":"e30-brake-fluid-flush","title":"Brake fluid flush and bleeding","system":"brakes","engines":["M20"],"level":"Intermediate","kind":"replacement","duration":"45–90 min","durationBasis":"Planning estimate for stock hardware in serviceable condition.","summary":"1991 U.S. 325i coupe, M20, rear-wheel drive. Factory hydraulic brakes. Use the procedure for the installed ABS or non-ABS system.","reviewStatus":"draft","sourceChecked":true,"applicability":"1991 U.S. 325i coupe, M20, rear-wheel drive. Factory hydraulic brakes. Use the procedure for the installed ABS or non-ABS system.","source":{"id":"e30-factory-repair-upload","title":"BMW E30 Repair Manual","section":"34-2 · 34 00 046 / 047","pdfPages":[641]},"evidence":[{"label":"BMW · 34-2, conventional and ABS bleeding","href":"/manual/34?pdf=641"}],"tools":["7 mm or 9 mm six-point bleeder wrench, according to the fitted screw.","Reservoir pressure bleeder, clear hose, catch bottle and low-range torque wrench."],"cautions":["Chock the wheels and support the car on rated stands or a lift before removing a wheel. A jack alone is insufficient.","Pump the pedal until firm before moving the car. Stop if the pedal sinks, a leak appears or the brakes drag.","Brake fluid damages paint. Do not let the reservoir run dry or exceed the pressure limit."],"jobSupport":{"reviewedOn":"2026-11-16","sourceSha256":"fa72b3321315a2f2a0f4df6d6879eae4ec7c639f8b0f6f41fd154adcb0a4f095","requiredParts":["Fresh approved brake fluid in a sealed container."],"conditionalParts":[],"stopConditions":[],"steps":[{"number":1,"tools":[],"source":{"printed":"34-2 · 34 00 046 / 047","pdf":641,"href":"/manual/34?pdf=641"}},{"number":2,"tools":[],"source":{"printed":"34-2 · 34 00 046 / 047","pdf":641,"href":"/manual/34?pdf=641"}},{"number":3,"tools":[],"source":{"printed":"34-2 · 34 00 046 / 047","pdf":641,"href":"/manual/34?pdf=641"}}]},"steps":[{"title":"Identify ABS and prepare the bleeder","body":"Use the fresh fluid specified for the installed brake system. Connect a reservoir pressure bleeder with a sound cap gasket. BMW gives a 2 bar maximum for the pressure equipment on this page.","check":"The bleeder holds pressure without leaks and the reservoir stays supplied."},{"title":"Bleed in the correct sequence","body":"For ABS, follow 34 00 047. Start at the right rear, then left rear, right front and left front. At each wheel, hold the pedal down and open the bleeder. Release the pedal and stroke it fully 12 times. Hold it down, close the bleeder, then release the pedal. For conventional brakes, use 34 00 046 and close each bleeder when the fluid is clear of air.","check":"Fresh, bubble-free fluid emerges from each bleed hose."},{"title":"Close the bleeders and check","body":"Tighten a 7 mm wrench-size bleeder to 5 Nm or a 9 mm one to 6 Nm. Release bleeder pressure before removing the cap, set the reservoir level and check at all four wheels.","check":"No fluid leaks and a held pedal stays firm."}]}'::jsonb),
  ('fb71b04fc5378cc3b83a1c68', '{"slug":"e30-front-control-arm","title":"Front control arm replacement","system":"suspension","engines":["M20"],"level":"Advanced","kind":"replacement","duration":"1–2 hr per side","durationBasis":"Planning estimate for stock hardware in serviceable condition.","summary":"1991 U.S. E30 325i coupe, original rear-wheel-drive front axle. Factory steel wishbones; use the separate procedure for the 325iX or M3.","reviewStatus":"draft","sourceChecked":true,"applicability":"1991 U.S. E30 325i coupe, original rear-wheel-drive front axle. Factory steel wishbones; use the separate procedure for the 325iX or M3.","source":{"id":"e30-factory-repair-upload","title":"BMW E30 Repair Manual","section":"31-6 · front wishbone replacement","pdfPages":[507]},"evidence":[{"label":"BMW · 31-6, front control arm replacement","href":"/manual/31?pdf=507"},{"label":"1991 325i coupe · front wishbone and bushing diagram","href":"https://www.bmwpartsdeal.com/parts-list/1991-bmw-325i-coupe_e30/front_rear_axle/front_axle_support_wishbone.html"}],"tools":["BMW 31 1 110 ball joint separator for the standard strut.","Torque wrench covering 42–85 Nm. Use the socket that fully fits each replacement nut."],"cautions":["Chock the wheels and support the car on rated stands or a lift before removing a wheel. A jack alone is insufficient.","Keep both ball-joint tapers and their seats clean and dry. Fit locking hardware that matches each joint."],"jobSupport":{"reviewedOn":"2026-11-16","sourceSha256":"fa72b3321315a2f2a0f4df6d6879eae4ec7c639f8b0f6f41fd154adcb0a4f095","requiredParts":["Wishbone for the correct side and its locking hardware."],"conditionalParts":[],"stopConditions":[],"steps":[{"number":1,"tools":[],"source":{"printed":"31-6 · front wishbone replacement","pdf":507,"href":"/manual/31?pdf=507"}},{"number":2,"tools":[],"source":{"printed":"31-6 · front wishbone replacement","pdf":507,"href":"/manual/31?pdf=507"}},{"number":3,"tools":[],"source":{"printed":"31-6 · front wishbone replacement","pdf":507,"href":"/manual/31?pdf=507"}}]},"steps":[{"title":"Match the replacement arm","body":"Check the side, steel arm and bushing position against the original. Support the hub so the brake hose cannot be pulled.","check":"The replacement arm, bracket and fasteners match the RWD application."},{"title":"Release the joints and bracket","body":"Remove the inner and outer joint nuts and separate the tapered joint with the factory separator specified for the strut. Unbolt the rear bushing bracket and withdraw the arm.","check":"The dust boots, hub and hose are clear of the tool path."},{"title":"Fit the arm and verify steering","body":"Seat the joints and install the specified locking nuts. Tighten the inner joint to 85 Nm, outer joint to 65 Nm and bracket to 42 Nm. Check for full steering travel and arrange an alignment.","check":"The joints are seated, boots intact and alignment checked before normal use."}]}'::jsonb),
  ('76dc0bd4a37aaa98a166d94b', '{"slug":"e30-tie-rod","title":"Steering tie rod and outer end","system":"suspension","engines":["M20"],"level":"Advanced","kind":"replacement","duration":"1–2 hr per side","durationBasis":"Planning estimate for stock hardware in serviceable condition.","summary":"1991 U.S. E30 325i coupe, original rear-wheel-drive front axle. Rack-and-pinion steering. Match the fitted lock plate and the steering damper arrangement.","reviewStatus":"draft","sourceChecked":true,"applicability":"1991 U.S. E30 325i coupe, original rear-wheel-drive front axle. Rack-and-pinion steering. Match the fitted lock plate and the steering damper arrangement.","source":{"id":"e30-factory-repair-upload","title":"BMW E30 Repair Manual","section":"32-8 · 32 21 251","pdfPages":[583]},"evidence":[{"label":"BMW · 32-8, tie rod replacement","href":"/manual/32?pdf=583"},{"label":"1991 325i coupe · steering linkage diagram","href":"https://www.bmwpartsdeal.com/parts-list/1991-bmw-325i-coupe_e30/steering_drive_shaft/steering_linkage_tie_rods.html"}],"tools":["BMW 32 2 070 separator for the outer joint.","BMW 32 2 100 for the standard inner joint, or 32 2 110 for the steering-damper version shown. Use pliers on the lock plate."],"cautions":["Chock the wheels and support the car on rated stands or a lift before removing a wheel. A jack alone is insufficient.","Preserve the rack boot seal. A measured starting length still requires alignment."],"jobSupport":{"reviewedOn":"2026-11-16","sourceSha256":"fa72b3321315a2f2a0f4df6d6879eae4ec7c639f8b0f6f41fd154adcb0a4f095","requiredParts":["Tie rod for the installed rack, new securing plate and outer locking hardware."],"conditionalParts":[],"stopConditions":[],"steps":[{"number":1,"tools":[],"source":{"printed":"32-8 · 32 21 251","pdf":583,"href":"/manual/32?pdf=583"}},{"number":2,"tools":[],"source":{"printed":"32-8 · 32 21 251","pdf":583,"href":"/manual/32?pdf=583"}},{"number":3,"tools":[],"source":{"printed":"32-8 · 32 21 251","pdf":583,"href":"/manual/32?pdf=583"}}]},"steps":[{"title":"Record the existing adjustment","body":"Center the steering and measure the fitted tie rod between repeatable points. Record the length before loosening the adjuster.","check":"A starting length is recorded for the same side of the car."},{"title":"Release the outer and inner joints","body":"Use the extractor for the tapered stud. Release the boot and securing plate, then remove the inner joint using the BMW tool that matches the fitted rack.","check":"The rack threads and boot sealing surfaces are undamaged."},{"title":"Refit, secure and align","body":"Use a new securing plate and tighten the inner joint to 75 Nm. Fit the correct outer locking hardware and tighten the stud to 36.5 ± 3.5 Nm. Set the recorded length, then have toe set and the adjuster clamp tightened to 14 Nm under normal load.","check":"The rack boot is sealed, the steering moves freely and toe is set."}]}'::jsonb),
  ('348b69c94a33d1528cd28436', '{"slug":"e30-front-wheel-bearing","title":"Front hub and wheel bearing","system":"suspension","engines":["M20"],"level":"Advanced","kind":"replacement","duration":"1–2 hr per side","durationBasis":"Planning estimate for stock hardware in serviceable condition.","summary":"1991 U.S. E30 325i coupe, original rear-wheel-drive front axle. RWD stub axle with a hub and integral bearing. The 325iX bearing is pressed into a different assembly.","reviewStatus":"draft","sourceChecked":true,"applicability":"1991 U.S. E30 325i coupe, original rear-wheel-drive front axle. RWD stub axle with a hub and integral bearing. The 325iX bearing is pressed into a different assembly.","source":{"id":"e30-factory-repair-upload","title":"BMW E30 Repair Manual","section":"31-10 to 31-10.1 · 31 21 180","pdfPages":[514,515]},"evidence":[{"label":"BMW · 31-10, RWD front hub removal","href":"/manual/31?pdf=514"},{"label":"BMW · 31-10.1, installing the new hub","href":"/manual/31?pdf=515"},{"label":"Baum Tools · front hub sockets, 36 mm and 46 mm","href":"https://www.myclassicparts.com/wp-content/uploads/2021/10/01_BMW_Baum_Tools_Catalogue.pdf"},{"label":"1991 325i coupe · front hub and wheel bearing diagram","href":"https://www.bmwpartsdeal.com/parts-list/1991-bmw-325i-coupe_e30/front_rear_axle/wheel_bearings.html"}],"tools":["36 mm thin-wall six-point socket for the original M24 collar nut (BMW 11 2 180).","BMW 31 2 101 / 102 / 104 hub puller set and 31 2 120 installer, or the correct equivalents.","Torque wrench rated for 290 Nm; staking tool for the new nut."],"cautions":["Chock the wheels and support the car on rated stands or a lift before removing a wheel. A jack alone is insufficient.","Keep grease off the disc and lining. Support the caliper independently of its hose.","Use a new collar nut and grease cap. Check the separate 325iX procedure if the hub is driven."],"jobSupport":{"reviewedOn":"2026-11-16","sourceSha256":"fa72b3321315a2f2a0f4df6d6879eae4ec7c639f8b0f6f41fd154adcb0a4f095","requiredParts":["Hub with integral bearing, collar nut and grease cap."],"conditionalParts":[],"stopConditions":[],"steps":[{"number":1,"tools":[],"source":{"printed":"31-10 to 31-10.1 · 31 21 180","pdf":514,"href":"/manual/31?pdf=514"}},{"number":2,"tools":[],"source":{"printed":"31-10 to 31-10.1 · 31 21 180","pdf":515,"href":"/manual/31?pdf=515"}},{"number":3,"tools":[],"source":{"printed":"31-10 to 31-10.1 · 31 21 180","pdf":515,"href":"/manual/31?pdf=515"}}]},"steps":[{"title":"Expose the RWD hub","body":"Remove the disc and hang the caliper. Lift the grease cap, then release the staking on the M24 collar nut before using a 36 mm thin-wall socket.","check":"The stub axle threads and ABS sensor are undamaged."},{"title":"Pull off the hub and fit the new unit","body":"Use BMW’s puller and installer arrangement. If a bearing race stays on the stub axle, use the specified race puller. Clean and inspect the journal before seating the new hub.","check":"The hub seats fully without hammering through the bearing."},{"title":"Torque, stake and check","body":"Tighten the new collar nut to 290 Nm, stake it and install the cap. Refit the brakes and wheel, check free rotation and verify that there is no bearing play.","check":"The staking is secure and the brake pedal is firm."}]}'::jsonb),
  ('e4b7cd037f0f2a56e024f5f4', '{"slug":"e30-front-strut","title":"Front strut, upper mount and damper","system":"suspension","engines":["M20"],"level":"Advanced","kind":"replacement","duration":"2–4 hr per side","durationBasis":"Planning estimate for stock hardware in serviceable condition.","summary":"1991 U.S. E30 325i coupe, original rear-wheel-drive front axle. Check the damper and upper mount type before applying shaft torque.","reviewStatus":"draft","sourceChecked":true,"applicability":"1991 U.S. E30 325i coupe, original rear-wheel-drive front axle. Check the damper and upper mount type before applying shaft torque.","source":{"id":"e30-factory-repair-upload","title":"BMW E30 Repair Manual","section":"31-11 to 31-14 · 31 31 000 / 31 32 001","pdfPages":[516,519,520,521]},"evidence":[{"label":"BMW · 31-11, front strut removal","href":"/manual/31?pdf=516"},{"label":"BMW · 31-13, spring compressor and shaft counterhold","href":"/manual/31?pdf=520"},{"label":"BMW · 31-14, retaining ring and parts order","href":"/manual/31?pdf=521"},{"label":"1991 325i coupe · front upper mount diagram","href":"https://www.bmwpartsdeal.com/parts-list/1991-bmw-325i-coupe_e30/front_rear_axle/guide_support_spring_pad_attaching_parts.html"},{"label":"1991 325i coupe · front strut and damper diagram","href":"https://www.bmwpartsdeal.com/parts-list/1991-bmw-325i-coupe_e30/front_rear_axle/front_spring_strut_shock_absorber.html"}],"tools":["BMW 31 3 111 spring compressor with the fitting shown, and 31 3 170 shaft-nut tool with a counterhold.","BMW 31 3 150 or 31 3 180 retaining-ring tool, according to the installed collar."],"cautions":["Chock the wheels and support the car on rated stands or a lift before removing a wheel. A jack alone is insufficient.","Never release the shaft nut while the spring bears on the mount. Use a compressor with the correct hooks for the spring."],"jobSupport":{"reviewedOn":"2026-11-16","sourceSha256":"fa72b3321315a2f2a0f4df6d6879eae4ec7c639f8b0f6f41fd154adcb0a4f095","requiredParts":["Matched strut inserts or mount components as required and new upper-mount locking nuts."],"conditionalParts":[],"stopConditions":[],"steps":[{"number":1,"tools":[],"source":{"printed":"31-11 to 31-14 · 31 31 000 / 31 32 001","pdf":516,"href":"/manual/31?pdf=516"}},{"number":2,"tools":[],"source":{"printed":"31-11 to 31-14 · 31 31 000 / 31 32 001","pdf":520,"href":"/manual/31?pdf=520"}},{"number":3,"tools":[],"source":{"printed":"31-11 to 31-14 · 31 31 000 / 31 32 001","pdf":521,"href":"/manual/31?pdf=521"}},{"number":4,"tools":[],"source":{"printed":"31-11 to 31-14 · 31 31 000 / 31 32 001","pdf":516,"href":"/manual/31?pdf=516"}}]},"steps":[{"title":"Remove the strut assembly","body":"Support the hub and brake caliper. Disconnect the links shown on page 31-11 and clear the hose and sensor leads before releasing the top mount.","check":"The assembly comes out without pulling on brake or sensor lines."},{"title":"Unload the upper mount","body":"Check the parts order on 31-12. Fit BMW 31 3 111 or a correctly sized equivalent and compress the spring until it is free of the mount. Counterhold the shaft with the tool specified for its head.","check":"The compressor is seated securely and the spring is unloaded at its ends."},{"title":"Replace the insert or upper mount","body":"Use the established collar tool for the cartridge. Assemble the isolators, spring and mount in BMW’s order. Select the shaft-nut torque using the actual internal or external hex design from the specification card.","check":"The spring ends are in their seats before the compressor is removed."},{"title":"Install and check alignment","body":"Install the complete strut with new locking nuts at the upper body mount and tighten them to 22 Nm. Use the linked front axle specifications for the joints disturbed during removal. Restore hose support and have alignment checked.","check":"Steering moves freely with no contact or tension on the leads."}]}'::jsonb),
  ('89cd1d43bd4281a318fd65e7', '{"slug":"e30-m20-spark-plugs","title":"M20 spark plugs","system":"engine","engines":["M20"],"level":"Beginner","kind":"replacement","duration":"30–60 min","durationBasis":"Planning estimate for stock hardware in serviceable condition.","summary":"E30 325i with the original M20 and factory-type M14 × 1.25 plugs. Install six of the same type.","reviewStatus":"draft","sourceChecked":true,"applicability":"E30 325i with the original M20 and factory-type M14 × 1.25 plugs. Install six of the same type.","source":{"id":"e30-factory-repair-upload","title":"BMW E30 Repair Manual","section":"12 12 · M20 ignition wires and spark plugs","pdfPages":[]},"evidence":[{"label":"BMW TIS 12 12 · Spark plugs","href":"https://workshop-manuals.com/bmw/3_series_e30/325i_m20_sal/4_tightening_torques/12__engine_electrical_system_(m20)/12__ignition_wires_spark_plugs/1_azd__spark_plugs/"},{"label":"BMW E30 torque manual · 12-2 · PDF 39","href":"https://www.allcarmanuals.com/factory-service-manual-343-BMW-3-Series-E30.html"},{"label":"BMW spark plug application chart","href":"https://bmwtechinfo.bmwgroup.com/sib_attachments/B120199SparkPlugChart.pdf"},{"label":"NGK · ZGR5A socket size","href":"https://www.ngkntk.com/part-finder/quad-atv/spark-plugs/bush-hog/trail-hunter-zgr5a-1/"},{"label":"BMW · tool 12 1 180","href":"https://workshop-manuals.com/bmw/3_series_e30/325i_m20_conver/10_special_tool/12__engine_electrical_system_(m20)/1_swz__pliers/"},{"label":"1991 325i sedan · ignition wiring diagram","href":"https://www.bmwpartsdeal.com/parts-list/1991-bmw-325i-sedan_e30/engine_electrical_system/ignition_wiring.html"}],"tools":["21 mm (13/16 in nominal) spark plug socket for the listed Bosch W-series plugs.","20.8 mm (13/16 in) deep spark plug socket for NGK ZGR5A.","BMW 12 1 180 plug-lead pliers for original connectors. Pull by the boot."],"cautions":["Let the engine cool before working around the plugs, fan or exhaust.","Work on one lead at a time. Start the new plug by hand to protect the head threads."],"jobSupport":{"reviewedOn":"2026-11-16","sourceSha256":"fa72b3321315a2f2a0f4df6d6879eae4ec7c639f8b0f6f41fd154adcb0a4f095","requiredParts":["Six identical spark plugs approved for the installed M20."],"conditionalParts":[],"stopConditions":[],"steps":[{"number":1,"tools":[],"source":{"printed":"BMW TIS 12 12 · Spark plugs","href":"https://workshop-manuals.com/bmw/3_series_e30/325i_m20_sal/4_tightening_torques/12__engine_electrical_system_(m20)/12__ignition_wires_spark_plugs/1_azd__spark_plugs/"}},{"number":2,"tools":[],"source":{"printed":"BMW TIS 12 12 · Spark plugs","href":"https://workshop-manuals.com/bmw/3_series_e30/325i_m20_sal/4_tightening_torques/12__engine_electrical_system_(m20)/12__ignition_wires_spark_plugs/1_azd__spark_plugs/"}},{"number":3,"tools":[],"source":{"printed":"BMW TIS 12 12 · Spark plugs","href":"https://workshop-manuals.com/bmw/3_series_e30/325i_m20_sal/4_tightening_torques/12__engine_electrical_system_(m20)/12__ignition_wires_spark_plugs/1_azd__spark_plugs/"}}]},"steps":[{"title":"Identify the plug and socket","body":"Match the factory application before opening the plug boxes. Use a 21 mm deep spark plug socket for the listed Bosch W-series plugs or 20.8 mm (13/16 in) for NGK ZGR5A. Check the gap only where the plug maker permits adjustment.","check":"All six plugs are the same approved type."},{"title":"Remove and inspect","body":"Pull each connector by its boot with the specified plug-lead pliers. Clear grit from around the plug before removing it. Record the condition by cylinder if the old plugs show unusual deposits.","check":"The plug holes are clean and the leads remain in firing order."},{"title":"Install and check","body":"Install the plugs by hand, then tighten the clean, dry factory-type M14 plugs to 30 ± 3 Nm, subject to the replacement plug’s installation instructions. Refit the connector fully and check for a smooth idle after all six are installed.","check":"Every boot is seated and the engine runs evenly."}]}'::jsonb),
  ('0a3c8eb9396bcabf5e2df710', '{"slug":"e30-m20-alternator-terminals","title":"M20 alternator terminals","system":"electrical","engines":["M20"],"level":"Intermediate","kind":"replacement","duration":"25–45 min","durationBasis":"Planning estimate for stock hardware in serviceable condition.","summary":"1991 U.S. 325i coupe, M20, rear-wheel drive.","reviewStatus":"draft","sourceChecked":true,"applicability":"1991 U.S. 325i coupe, M20, rear-wheel drive.","source":{"id":"e30-factory-repair-upload","title":"BMW E30 Repair Manual","section":"12 31 · M20 alternator terminals","pdfPages":[]},"evidence":[{"label":"BMW E30 torque manual · 12-5 · PDF 42","href":"https://www.allcarmanuals.com/factory-service-manual-343-BMW-3-Series-E30.html"},{"label":"1989 BMW 325i ETM · charging circuit","href":"https://www.e30club.ru/stuff/electric/e30_89.pdf#page=29"},{"label":"1991 325i coupe · alternator diagram","href":"https://www.bmwpartsdeal.com/parts-list/1991-bmw-325i-coupe_e30/engine_electrical_system/alternator.html"}],"tools":["13 mm six-point socket for a standard M8 B+ hex nut. Match the D+ nut on the fitted alternator.","Low-range torque wrench covering 5–13 Nm."],"cautions":["Let the engine cool before working around the plugs, fan or exhaust.","Disconnect the battery negative cable before touching B+. Do not bridge a live output terminal to the case."],"jobSupport":{"reviewedOn":"2026-11-16","sourceSha256":"fa72b3321315a2f2a0f4df6d6879eae4ec7c639f8b0f6f41fd154adcb0a4f095","requiredParts":[],"conditionalParts":[],"stopConditions":[],"steps":[{"number":1,"tools":[],"source":{"printed":"BMW E30 torque manual · 12-5 · PDF 42","href":"https://www.allcarmanuals.com/factory-service-manual-343-BMW-3-Series-E30.html"}},{"number":2,"tools":[],"source":{"printed":"BMW E30 torque manual · 12-5 · PDF 42","href":"https://www.allcarmanuals.com/factory-service-manual-343-BMW-3-Series-E30.html"}},{"number":3,"tools":[],"source":{"printed":"BMW E30 torque manual · 12-5 · PDF 42","href":"https://www.allcarmanuals.com/factory-service-manual-343-BMW-3-Series-E30.html"}}]},"steps":[{"title":"Identify the terminals","body":"Use the matching electrical diagram and alternator markings to distinguish B+ from D+. Photograph the cable positions before disconnecting anything.","check":"The alternator label and both terminal markings are readable."},{"title":"Refit and tighten","body":"Clean the mating faces and reinstall the leads without letting the studs turn. Use 13 Nm on factory M20 B+ and 5 Nm on D+ after confirming the alternator type.","check":"Both leads sit flat and the terminal insulation is intact."},{"title":"Restore insulation and test","body":"Refit the B+ cover before reconnecting the battery. Verify that the charge warning lamp comes on with ignition and goes out after starting.","check":"The wiring is covered and the warning lamp behaves normally."}]}'::jsonb),
  ('9ba36eec89f2fb1608e2413e', '{"slug":"e30-manual-gearbox-fluid","title":"Getrag 260 manual gearbox oil","system":"drivetrain","engines":["M20"],"level":"Intermediate","kind":"replacement","duration":"45–75 min","durationBasis":"Planning estimate for stock hardware in serviceable condition.","summary":"1991 U.S. 325i coupe, M20, rear-wheel drive. Identify the original Getrag 260/5 and read the fluid label on the installed case.","reviewStatus":"draft","sourceChecked":true,"applicability":"1991 U.S. 325i coupe, M20, rear-wheel drive. Identify the original Getrag 260/5 and read the fluid label on the installed case.","source":{"id":"e30-factory-repair-upload","title":"BMW E30 Repair Manual","section":"00 11 229 · Manual transmission oil change","pdfPages":[]},"evidence":[{"label":"BMW · 00 11 229, manual gearbox oil change","href":"https://workshop-manuals.com/bmw/3_series_e36/325i_m50_coupe/2_repair_instructions/0__maintenance_and_general_data/64_ra__oil_change_in_manual_transmission/"},{"label":"BMW E30 torque manual · 23-2 · PDF 71","href":"https://www.allcarmanuals.com/factory-service-manual-343-BMW-3-Series-E30.html"},{"label":"1991 325i coupe · Getrag 260 housing and plug diagram","href":"https://www.bmwpartsdeal.com/parts-list/1991-bmw-325i-coupe_e30/manual_transmission/housing_attaching_parts_getrag_260_5_50.html"}],"tools":["Oil pump or filling hose, drain pan, level supported lift and torque wrench. Match the socket or hex bit to the installed plugs."],"cautions":["Chock the wheels and support the car on rated stands or a lift before removing a wheel. A jack alone is insufficient.","Identify the original Getrag 260 and its fluid label before draining. Similar cases may use different fluids."],"jobSupport":{"reviewedOn":"2026-11-16","sourceSha256":"fa72b3321315a2f2a0f4df6d6879eae4ec7c639f8b0f6f41fd154adcb0a4f095","requiredParts":["Approved fluid identified from the Getrag case label."],"conditionalParts":[],"stopConditions":[],"steps":[{"number":1,"tools":[],"source":{"printed":"BMW · 00 11 229, manual gearbox oil change","href":"https://workshop-manuals.com/bmw/3_series_e36/325i_m50_coupe/2_repair_instructions/0__maintenance_and_general_data/64_ra__oil_change_in_manual_transmission/"}},{"number":2,"tools":[],"source":{"printed":"BMW · 00 11 229, manual gearbox oil change","href":"https://workshop-manuals.com/bmw/3_series_e36/325i_m50_coupe/2_repair_instructions/0__maintenance_and_general_data/64_ra__oil_change_in_manual_transmission/"}},{"number":3,"tools":[],"source":{"printed":"BMW · 00 11 229, manual gearbox oil change","href":"https://workshop-manuals.com/bmw/3_series_e36/325i_m50_coupe/2_repair_instructions/0__maintenance_and_general_data/64_ra__oil_change_in_manual_transmission/"}}]},"steps":[{"title":"Confirm the fluid and access","body":"Check the case label and identify both plugs. Support the car level and confirm the fill plug can be removed.","check":"You have the correct fluid and can refill the gearbox."},{"title":"Drain the gearbox","body":"Remove the lower plug and collect the old fluid. Clean the magnet, inspect for large debris and refit the original-style drain plug at 50 Nm.","check":"The plug and mating face are clean and the threads are sound."},{"title":"Refill at the lower edge of the fill opening","body":"With the vehicle level, pump in the approved fluid until it reaches the lower edge of the opening. Seal the original fill plug at 50 Nm and clean the case so a leak is visible.","check":"The fill level is correct and both plugs stay dry."}]}'::jsonb),
  ('bb9fe3376ec9b7f94fdb4dc4', '{"slug":"e30-4hp22-sump","title":"ZF 4HP22 transmission pan and fluid","system":"drivetrain","engines":["M20"],"level":"Intermediate","kind":"replacement","duration":"1–2 hr","durationBasis":"Planning estimate for stock hardware in serviceable condition.","summary":"1991 U.S. 325i coupe, M20, rear-wheel drive. ZF 4HP22 with the original dipstick, drain plug and steel pan. Read the gearbox plate and fluid recommendation first.","reviewStatus":"draft","sourceChecked":true,"applicability":"1991 U.S. 325i coupe, M20, rear-wheel drive. ZF 4HP22 with the original dipstick, drain plug and steel pan. Read the gearbox plate and fluid recommendation first.","source":{"id":"e30-factory-repair-upload","title":"BMW E30 Repair Manual","section":"24-110 · 24 11 002","pdfPages":[388]},"evidence":[{"label":"BMW · 24-110, 4HP22 oil sump","href":"/manual/24?pdf=388"},{"label":"BMW · 24-113, oil screen and hydraulic control","href":"/manual/24?pdf=392"},{"label":"1991 325i coupe · 4HP22 pan and housing diagram","href":"https://www.bmwpartsdeal.com/parts-list/1991-bmw-325i-coupe_e30/automatic_transmission/housing_parts_lubrication_system_zf_4hp22_24.html"}],"tools":["BMW 24 0 080 filling funnel, drain pan and level lift.","Low-range torque wrench covering 7–16 Nm. Check the installed pan screws and plug before choosing sockets."],"cautions":["Chock the wheels and support the car on rated stands or a lift before removing a wheel. A jack alone is insufficient.","Let hot fluid cool before draining. Stop if the fluid is burnt or contains substantial debris. Diagnosis comes before a refill."],"jobSupport":{"reviewedOn":"2026-11-16","sourceSha256":"fa72b3321315a2f2a0f4df6d6879eae4ec7c639f8b0f6f41fd154adcb0a4f095","requiredParts":["Approved ATF for the identified transmission, profile gasket and drain plug seal."],"conditionalParts":[],"stopConditions":[],"steps":[{"number":1,"tools":[],"source":{"printed":"24-110 · 24 11 002","pdf":388,"href":"/manual/24?pdf=388"}},{"number":2,"tools":[],"source":{"printed":"24-110 · 24 11 002","pdf":388,"href":"/manual/24?pdf=388"}},{"number":3,"tools":[],"source":{"printed":"24-110 · 24 11 002","pdf":388,"href":"/manual/24?pdf=388"}}]},"steps":[{"title":"Identify the pan and drain","body":"Read the transmission tag. Confirm the fitted pan, dipstick, plug and replacement gasket. Drain the ATF with the car supported level.","check":"The drain plug matches the M10 specification and the drained fluid has been inspected."},{"title":"Clean and refit the pan","body":"Disconnect the dipstick tube fitting and remove the pan. Clean the pan and both magnets. Refit them and a new profile gasket with the pan bracket orientation shown in the manual. Use the E30 archive’s 7 Nm for its original M6 pan screws and 16 Nm for the original M10 drain plug.","check":"Both magnets are in place, the gasket has stayed seated and the tube is sealed."},{"title":"Refill and check at temperature","body":"Use the BMW filling funnel and approved fresh ATF. Follow the manual’s dipstick marks for the initial fill. Recheck at about 80 °C on level ground with the selector in P and engine idling.","check":"The level is within the marked range at the specified temperature and the pan and tube are dry."}]}'::jsonb),
  ('7bd432651993caf5bc45726f', '{"slug":"e30-m20-starter-terminals","title":"M20 starter terminals","system":"electrical","engines":["M20"],"level":"Intermediate","kind":"replacement","duration":"25–45 min","durationBasis":"Planning estimate for stock hardware in serviceable condition.","summary":"1991 U.S. 325i coupe, M20, rear-wheel drive.","reviewStatus":"draft","sourceChecked":true,"applicability":"1991 U.S. 325i coupe, M20, rear-wheel drive.","source":{"id":"e30-factory-repair-upload","title":"BMW E30 Repair Manual","section":"12 41 · Starter wiring connections","pdfPages":[]},"evidence":[{"label":"BMW E30 torque manual · 12-6 · PDF 43","href":"https://www.allcarmanuals.com/factory-service-manual-343-BMW-3-Series-E30.html"},{"label":"1989 BMW 325i ETM · manual starter circuit","href":"https://www.e30club.ru/stuff/electric/e30_89.pdf#page=31"},{"label":"1991 325i coupe · starter diagram","href":"https://www.bmwpartsdeal.com/parts-list/1991-bmw-325i-coupe_e30/engine_electrical_system/starter.html"}],"tools":["8 mm, 10 mm and 13 mm six-point sockets for standard M5, M6 and M8 hex nuts, respectively. Confirm the fitted nut profile.","Low-range torque wrench covering 5–12 Nm."],"cautions":["Let the engine cool before working around the plugs, fan or exhaust.","Disconnect the battery negative cable before uncovering the starter supply terminal."],"jobSupport":{"reviewedOn":"2026-11-16","sourceSha256":"fa72b3321315a2f2a0f4df6d6879eae4ec7c639f8b0f6f41fd154adcb0a4f095","requiredParts":[],"conditionalParts":[],"stopConditions":[],"steps":[{"number":1,"tools":[],"source":{"printed":"BMW E30 torque manual · 12-6 · PDF 43","href":"https://www.allcarmanuals.com/factory-service-manual-343-BMW-3-Series-E30.html"}},{"number":2,"tools":[],"source":{"printed":"BMW E30 torque manual · 12-6 · PDF 43","href":"https://www.allcarmanuals.com/factory-service-manual-343-BMW-3-Series-E30.html"}},{"number":3,"tools":[],"source":{"printed":"BMW E30 torque manual · 12-6 · PDF 43","href":"https://www.allcarmanuals.com/factory-service-manual-343-BMW-3-Series-E30.html"}}]},"steps":[{"title":"Identify the starter and its connections","body":"Confirm the starter label and note the wiring position at each marked terminal. Compare the layout to the electrical manual for the installed transmission.","check":"Each cable is identified by the terminal marking on the starter."},{"title":"Inspect and reconnect","body":"Check the terminals for damaged threads and heat discoloration. Clean the cable eyelets and tighten the applicable factory nuts to 12 Nm on 30, 6 Nm on 50 and 5 Nm on 30h when fitted.","check":"The eyelets sit flat and no terminal has twisted."},{"title":"Refit insulation and check starting","body":"Cover the live terminal before reconnecting the battery. Verify that the starter engages and stops as expected when the key is released.","check":"Covers are secure and the starter works normally."}]}'::jsonb),
  ('006a93a7a3c4b1a14d8072c8', '{"slug":"e30-front-control-arm-bush","title":"Front wishbone bushings","system":"suspension","engines":["M20"],"level":"Advanced","kind":"replacement","duration":"1–2 hr per side","durationBasis":"Planning estimate for stock hardware in serviceable condition.","summary":"1991 U.S. E30 325i coupe, original rear-wheel-drive front axle. Use matching left and right bushings and keep their installation marks aligned.","reviewStatus":"draft","sourceChecked":true,"applicability":"1991 U.S. E30 325i coupe, original rear-wheel-drive front axle. Use matching left and right bushings and keep their installation marks aligned.","source":{"id":"e30-factory-repair-upload","title":"BMW E30 Repair Manual","section":"31-8 · 31 12 130","pdfPages":[510]},"evidence":[{"label":"BMW · 31-8, wishbone bushing installation","href":"/manual/31?pdf=510"},{"label":"1991 325i coupe · front wishbone and bushing diagram","href":"https://www.bmwpartsdeal.com/parts-list/1991-bmw-325i-coupe_e30/front_rear_axle/front_axle_support_wishbone.html"}],"tools":["BMW 31 2 130 press fixture for the bushing and bracket; feeler gauge for the factory wear check."],"cautions":["Chock the wheels and support the car on rated stands or a lift before removing a wheel. A jack alone is insufficient.","The bush is a press fit. Stop if the bracket or press fixture cannot be supported squarely."],"jobSupport":{"reviewedOn":"2026-11-16","sourceSha256":"fa72b3321315a2f2a0f4df6d6879eae4ec7c639f8b0f6f41fd154adcb0a4f095","requiredParts":["Matched left and right rubber mounts for the installed wishbones."],"conditionalParts":[],"stopConditions":[],"steps":[{"number":1,"tools":[],"source":{"printed":"31-8 · 31 12 130","pdf":510,"href":"/manual/31?pdf=510"}},{"number":2,"tools":[],"source":{"printed":"31-8 · 31 12 130","pdf":510,"href":"/manual/31?pdf=510"}},{"number":3,"tools":[],"source":{"printed":"31-8 · 31 12 130","pdf":510,"href":"/manual/31?pdf=510"}}]},"steps":[{"title":"Mark the brackets and check the bushes","body":"Identify each side and record the orientation marks. Confirm the replacement pair is for the six-cylinder RWD arm.","check":"The mounting style and marks match the factory illustration."},{"title":"Press in the new bushes","body":"Support each bracket in BMW 31 2 130 or the matching fixture. Align its mark with the new bush and press the bush in flush from the beveled end as shown.","check":"Each bush is flush and its marks align with its bracket."},{"title":"Refit and verify under normal load","body":"Refit the brackets and tighten them to 42 Nm. With the car at normal load, measure clearance A where the workshop drawing shows it.","check":"Clearance A measures 0.7–1.7 mm on both sides."}]}'::jsonb),
  ('ab11887e3d99ec682d92dff0', '{"slug":"e30-front-stabilizer","title":"Front anti-roll bar, links and mounts","system":"suspension","engines":["M20"],"level":"Intermediate","kind":"replacement","duration":"1–2 hr","durationBasis":"Planning estimate for stock hardware in serviceable condition.","summary":"1991 U.S. E30 325i coupe, original rear-wheel-drive front axle. Link mounts to the control arm; use different specs for an iX or M3 strut-mounted design.","reviewStatus":"draft","sourceChecked":true,"applicability":"1991 U.S. E30 325i coupe, original rear-wheel-drive front axle. Link mounts to the control arm; use different specs for an iX or M3 strut-mounted design.","source":{"id":"e30-factory-repair-upload","title":"BMW E30 Repair Manual","section":"31-17 · 31 35 000","pdfPages":[530]},"evidence":[{"label":"BMW · 31-17, front anti-roll bar","href":"/manual/31?pdf=530"},{"label":"1991 325i coupe · front stabilizer diagram","href":"https://www.bmwpartsdeal.com/parts-list/1991-bmw-325i-coupe_e30/front_rear_axle/stabilizer_front.html"}],"tools":["Counterhold wrench for the flats on the link. Measure the actual bar diameter before buying bushes."],"cautions":["Chock the wheels and support the car on rated stands or a lift before removing a wheel. A jack alone is insufficient.","Support the front evenly before disconnecting the bar. Confirm it is free of load at the links."],"jobSupport":{"reviewedOn":"2026-11-16","sourceSha256":"fa72b3321315a2f2a0f4df6d6879eae4ec7c639f8b0f6f41fd154adcb0a4f095","requiredParts":["Matched links or mount bushes for the measured bar diameter if replacing them."],"conditionalParts":[],"stopConditions":[],"steps":[{"number":1,"tools":[],"source":{"printed":"31-17 · 31 35 000","pdf":530,"href":"/manual/31?pdf=530"}},{"number":2,"tools":[],"source":{"printed":"31-17 · 31 35 000","pdf":530,"href":"/manual/31?pdf=530"}},{"number":3,"tools":[],"source":{"printed":"31-17 · 31 35 000","pdf":530,"href":"/manual/31?pdf=530"}}]},"steps":[{"title":"Identify the layout and measure the bar","body":"Compare the arm-mounted link and clamp positions with the BMW diagram. Measure the bare bar at the bushing seat before ordering rubber mounts.","check":"The link type and bush bore match the car."},{"title":"Release the bar","body":"Counterhold the links while disconnecting both ends. Release the left wishbone bracket as shown for access and remove both bar mounts.","check":"The bar comes out without contacting the steering or brake lines."},{"title":"Install and check clearance","body":"Refit the mounts and links, aligning the bar laterally. Tighten the link-to-bar nuts to 47 Nm and the factory M8 clamp fasteners to 22 Nm. Restore any link pivot bracket disturbed during the work to its 42 Nm specification.","check":"Both links articulate and the bar clears nearby components."}]}'::jsonb);
