begin;

on conflict (id, revision) do nothing;

create temporary table e30_guide_snapshots (
  revision text not null,
  content jsonb not null
) on commit drop;


select content->>'slug', content->>'system', content->>'title', content->'source'->>'id',
       content->'source'->>'section', array(select jsonb_array_elements_text(content->'engines')),
       content->>'reviewStatus', content
from e30_guide_snapshots
on conflict (id) do nothing;

select content->>'slug', revision, content
from e30_guide_snapshots
on conflict (guide_id, revision) do nothing;

select content->>'slug', revision, step_number, step->>'title'
from e30_guide_snapshots
cross join lateral jsonb_array_elements(content->'steps') with ordinality as indexed(step, step_number)
on conflict (guide_id, revision, step_number) do nothing;

commit;
